rriculum"}, {"id": "ce0edb8c-d9e3-47f2-b2fc-bdc8d0bbd0ff", "type": "concept", "title": "Null curriculum"}, {"id": "35e0d1bc-4b4a-417a-b784-366307c7efd4", "type": "concept", "title": "School norms"}, {"id": "338d1827-2023-4747-8d88-92f5880ea948", "type": "concept", "title": "Power and representation"}], "description": "Students learn that what schools do not teach, or teach implicitly, can matter as much as official content."}, {"id": "69cb6786-3570-48ea-8072-2f6c72e6cff5", "type": "subtopic", "title": "Curriculum Models", "children": [{"id": "776d1de7-f8f3-4528-9945-6213ece8853c", "type": "concept", "title": "Tyler rationale"}, {"id": "d733c404-6ca1-4fa3-bd0f-c40a609256e3", "type": "concept", "title": "Backward design"}, {"id": "6c0147c4-ce1e-40f1-85e7-8dd5f62f799b", "type": "concept", "title": "Inquiry-based design"}, {"id": "fd95cc8d-57a8-4f70-8b13-cd30ea8c8b5f", "type": "concept", "title": "Project-based learning"}], "description": "Models provide different design logics for organizing content, inquiry, skills, and transfer."}]}, {"id": "6f07da72-ce5e-403e-80ea-9577229ad7c7", "type": "topic", "title": "Standards, Competencies, Learning Progressions, and Curriculum Priorities", "description": "Translate standards and competencies into coherent learning priorities without letting standards become a checklist.", "children": [{"id": "33b6e12f-8710-41d6-964c-15fd5f794679", "type": "subtopic", "title": "Standards Literacy", "children": [{"id": "efe00662-1f00-406a-bd04-422e86ffca01", "type": "concept", "title": "Common Core"}, {"id": "a471a88b-e933-46cf-8f69-5e6008f75b2b", "type": "concept", "title": "NGSS"}, {"id": "422e8051-bb64-4959-850f-b871fd2c0bb6", "type": "concept", "title": "C3 Framework"}, {"id": "4f08d774-a31e-4a21-a3ac-ed60392fbfbf", "type": "concept", "title": "State standards"}], "description": "Teachers need to unpack standards into teachable ideas, practices, and performances."}, {"id": "4b5931e4-a1de-487c-8401-980835b0a1d5", "type": "subtopic", "title":