set
  title = 'Curriculum Design and Assessment',
  goal = 'Curriculum Design and Assessment',
  summary = 'Frame curriculum and assessment as one coherent system for learning, equity, evidence, and instructional decision making. Topics cover curriculum theory and purposes of schooling, standards, competencies, and learning progressions, backward design, unit and lesson planning, differentiation and Universal Design for Learning, curriculum mapping and alignment, formative and authentic assessment, rubrics and feedback, grading, portfolios, and self-assessment, validity, bias, and accommodations, ethical data use, materials review and implementation, and a capstone curriculum-assessment portfolio.',
  data = $cdasjson${"slug": "curriculum-design-and-assessment", "title": "Curriculum Design and Assessment", "description": "Frame curriculum and assessment as one coherent system for learning, equity, evidence, and instructional decision making. Topics cover curriculum theory and purposes of schooling, standards, competencies, and learning progressions, backward design, unit and lesson planning, differentiation and Universal Design for Learning, curriculum mapping and alignment, formative and authentic assessment, rubrics and feedback, grading, portfolios, and self-assessment, validity, bias, and accommodations, ethical data use, materials review and implementation, and a capstone curriculum-assessment portfolio.", "topics": [{"id": "8d64eec8-d4c1-42c7-817c-298b288ecde2", "type": "topic", "title": "Curriculum Design and Assessment as Integrated Practice", "description": "Frame curriculum and assessment as one coherent system for learning, equity, evidence, and instructional decision making.", "children": [{"id": "052541f3-56c3-4fe7-ac27-fb445e59bdaa", "type": "subtopic", "title": "Curriculum, Instruction, and Assessment Cycle", "children": [{"id": "ebdfbdf4-cba5-4e91-ad58-e9bfd163d3ab", "type": "concept", "title": "Learning goals"}, {"id": "2ec54251-ffa9-4b6f-bdc3-26283c578786", "type": "concept", "title": "Instructional experiences"}, {"id": "39a7f4ea-ecb3-4a90-9629-698ee4286390", "type": "concept", "title": "Assessment evidence"}, {"id": "ca8fc368-0525-45d2-b7ec-fb4f6b8802ba", "type": "concept", "title": "Revision and reteaching"}], "description": "This subtopic establishes that goals, teaching, evidence, and revision should work as one system."}, {"id": "9eca64b0-0671-4a25-a1d4-09070cf821b5", "type": "subtopic", "title": "Teacher Decision Making", "children": [{"id": "e5ddc2c5-8243-4da5-88a1-797a0e4921fe", "type": "concept", "title": "Context analysis"}, {"id": "b92969bf-30de-4622-80ce-c481731f30a7", "type": "concept", "title": "Learner knowledge"}, {"id": "f4dc3461-3b94-4b47-908e-f23fa7346745", "type": "concept", "title": "Content knowledge"}, {"id": "057d091d-55f3-44a2-bea9-95776328cb0f", "type": "concept", "title": "Instructional judgment"}], "description": "Curriculum design is a professional judgment process, not just filling in templates."}, {"id": "6eb282cd-8c00-44ce-8cfd-9760c44f4ff6", "type": "subtopic", "title": "Equity and Learning Evidence", "children": [{"id": "55b0276d-c8a5-41d0-9fe8-d96f67837c78", "type": "concept", "title": "Opportunity to learn"}, {"id": "f2f5b341-4089-4cca-94bf-cfd0ecf1a8d6", "type": "concept", "title": "Cultural responsiveness"}, {"id": "8b625c8d-35c5-4d71-967e-65af4920cedc", "type": "concept", "title": "Accessibility"}, {"id": "775475a9-bd66-4da5-bf6d-f7c16d1ff59d", "type": "concept", "title": "Fair interpretation"}], "description": "Assessment evidence must illuminate learning while avoiding deficit labels and avoidable barriers."}]}, {"id": "e7ef137d-1206-4ced-8df1-2826a715b955", "type": "topic", "title": "Curriculum Theory, Models, and Purposes of Schooling", "description": "Compare major curriculum traditions and how they shape what is taught, valued, excluded, and assessed.", "children": [{"id": "3ccfb8db-c8c6-4a4a-9381-8bd11d1d17e2", "type": "subtopic", "title": "Curriculum Traditions", "children": [{"id": "40bd1227-9e2d-42f0-bd6c-fccb2ad9ec73", "type": "concept", "title": "Traditional"}, {"id": "d7086e72-2ed6-4b13-8cca-755e83bb346d", "type": "concept", "title": "Progressive"}, {"id": "3b18714b-fbdd-4262-8785-3ae0fcf056df", "type": "concept", "title": "Critical"}, {"id": "2e20f96a-beab-4ca6-a1fe-5f18695e4c47", "type": "concept", "title": "Concept-based"}], "description": "Curriculum theory helps teachers understand why different models value different kinds of knowledge and learning."}, {"id": "27f418af-e8ba-4335-8fb3-bb1d786ddc0c", "type": "subtopic", "title": "Hidden and Null Curriculum", "children": [{"id": "1fdafa0f-2607-4e63-ade1-8a417a66adcd", "type": "concept", "title": "Hidden curriculum"}, {"id": "ce0edb8c-d9e3-47f2-b2fc-bdc8d0bbd0ff", "type": "concept", "title": "Null curriculum"}, {"id": "35e0d1bc-4b4a-417a-b784-366307c7efd4", "type": "concept", "title": "School norms"}, {"id": "338d1827-2023-4747-8d88-92f5880ea948", "type": "concept", "title": "Power and representation"}], "description": "Students learn that what schools do not teach, or teach implicitly, can matter as much as official content."}, {"id": "69cb6786-3570-48ea-8072-2f6c72e6cff5", "type": "subtopic", "title": "Curriculum Models", "children": [{"id": "776d1de7-f8f3-4528-9945-6213ece8853c", "type": "concept", "title": "Tyler rationale"}, {"id": "d733c404-6ca1-4fa3-bd0f-c40a609256e3", "type": "concept", "title": "Backward design"}, {"id": "6c0147c4-ce1e-40f1-85e7-8dd5f62f799b", "type": "concept", "title": "Inquiry-based design"}, {"id": "fd95cc8d-57a8-4f70-8b13-cd30ea8c8b5f", "type": "concept", "title": "Project-based learning"}], "description": "Models provide different design logics for organizing content, inquiry, skills, and transfer."}]}, {"id": "6f07da72-ce5e-403e-80ea-9577229ad7c7", "type": "topic", "title": "Standards, Competencies, Learning Progressions, and Curriculum Priorities", "description": "Translate standards and competencies into coherent learning priorities without letting standards become a checklist.", "children": [{"id": "33b6e12f-8710-41d6-964c-15fd5f794679", "type": "subtopic", "title": "Standards Literacy", "children": [{"id": "efe00662-1f00-406a-bd04-422e86ffca01", "type": "concept", "title": "Common Core"}, {"id": "a471a88b-e933-46cf-8f69-5e6008f75b2b", "type": "concept", "title": "NGSS"}, {"id": "422e8051-bb64-4959-850f-b871fd2c0bb6", "type": "concept", "title": "C3 Framework"}, {"id": "4f08d774-a31e-4a21-a3ac-ed60392fbfbf", "type": "concept", "title": "State standards"}], "description": "Teachers need to unpack standards into teachable ideas, practices, and performances."}, {"id": "4b5931e4-a1de-487c-8401-980835b0a1d5", "type": "subtopic", "title": "Learning Progressions", "children": [{"id": "0e9abc25-7e42-458f-8fa1-b345bf4b836c", "type": "concept", "title": "Prerequisite knowledge"}, {"id": "2f494714-203e-424d-bac6-92e4da5c71f7", "type": "concept", "title": "Conceptual growth"}, {"id": "20f63c1f-04e5-4955-b65f-17dfd0c7e7ef", "type": "concept", "title": "Skill development"}, {"id": "08772681-85fb-414e-a263-9a21b3e64415", "type": "concept", "title": "Developmental appropriateness"}], "description": "Progressions describe how understanding develops over time and help sequence instruction."}, {"id": "a2235c65-3f15-48eb-95a2-a6d16ed667c2", "type": "subtopic", "title": "Curriculum Prioritization", "children": [{"id": "d924fba6-8bf4-4924-bf8c-3d1c8ad30cdf", "type": "concept", "title": "Big ideas"}, {"id": "04fa0b03-0cfc-44d2-afe0-0363f75044d7", "type": "concept", "title": "Enduring understandings"}, {"id": "981a7cf4-0794-4961-868b-c1183e13dca9", "type": "concept", "title": "Power standards"}, {"id": "fb5e2eb6-11ae-4639-9f43-7e8e0f76535a", "type": "concept", "title": "Transfer goals"}], "description": "Prioritization keeps curriculum focused on durable, transferable learning rather than superficial coverage."}]}, {"id": "fac19ea5-42b8-4d0b-8309-f19a140f44b5", "type": "topic", "title": "Backward Design, Essential Questions, and Learning Objectives", "description": "Use backward design to align goals, evidence, learning experiences, and transfer.", "children": [{"id": "04d544c5-5884-4405-b0de-044cf61824d2", "type": "subtopic", "title": "Backward Design Logic", "children": [{"id": "c39a17f4-8921-4a7f-bcbf-ce7ec42ea0ca", "type": "concept", "title": "Stage 1 goals"}, {"id": "7f7f8156-3f4f-448d-b735-98239c80cb7d", "type": "concept", "title": "Stage 2 evidence"}, {"id": "22dfcf7f-f575-4249-a743-2f1f3d2880c7", "type": "concept", "title": "Stage 3 learning plan"}, {"id": "5ca872ba-faca-4535-b603-88cd54d49dcb", "type": "concept", "title": "Alignment checks"}], "description": "Backward design starts with desired learning and evidence before selecting activities."}, {"id": "b02fceed-3576-4148-b513-f29df941fb0d", "type": "subtopic", "title": "Essential Questions", "children": [{"id": "873d39ee-e1b9-4cba-b6ff-c7beb34240ea", "type": "concept", "title": "Open-ended questions"}, {"id": "bf81ab55-2ce6-4452-8a07-32700f8b37c3", "type": "concept", "title": "Disciplinary inquiry"}, {"id": "5bd41883-7a84-4880-9c47-8252ff32b61f", "type": "concept", "title": "Student curiosity"}, {"id": "5a537707-76ef-4876-be8d-7117dfd3248b", "type": "concept", "title": "Transfer beyond the unit"}], "description": "Essential questions invite inquiry, debate, transfer, and revisiting ideas over time."}, {"id": "873ded5e-033e-446d-aaa0-8f1d5c04c3f4", "type": "subtopic", "title": "Learning Objectives", "children": [{"id": "4f1c1de4-1c19-4ccb-9f60-198a58c12f36", "type": "concept", "title": "Observable verbs"}, {"id": "16d813a1-f434-487f-ba4d-1ed883733530", "type": "concept", "title": "Knowledge and skills"}, {"id": "017d9b86-751d-40fa-ba3d-f5bd574bd1d3", "type": "concept", "title": "Cognitive demand"}, {"id": "c3c6d282-0529-4cc4-aa45-a468e185fff9", "type": "concept", "title": "Success criteria links"}], "description": "Learning objectives make intended learning visible, assessable, and teachable."}]}, {"id": "a45380db-182c-4238-ab8f-c8b8c010d7c7", "type": "topic", "title": "Unit Planning, Lesson Design, and Learning Experiences", "description": "Design coherent units and lessons that support inquiry, practice, feedback, and deep understanding.", "children": [{"id": "73ad7b0a-3e89-44f4-9acb-d6343c0e2fbb", "type": "subtopic", "title": "Unit Architecture", "children": [{"id": "b78dd531-12fd-4e0f-b0fe-3498cd67fd8c", "type": "concept", "title": "Unit arc"}, {"id": "b9d78f32-9853-4fd0-af95-8f238f4d273c", "type": "concept", "title": "Sequencing"}, {"id": "c0e227ff-04e7-48ce-a5ab-65eee68f24ab", "type": "concept", "title": "Scaffolding"}, {"id": "b7b45543-752d-414b-8ae1-4fcf019f424c", "type": "concept", "title": "Culminating performance"}], "description": "Units organize learning over time so students build understanding rather than experience disconnected lessons."}, {"id": "16625b85-a902-48b5-b21d-4faaa6552c4a", "type": "subtopic", "title": "Lesson Design", "children": [{"id": "b420daa7-1db1-4f9f-90fd-75eda73413d2", "type": "concept", "title": "Launch"}, {"id": "d5f37e87-fc0f-4c54-9af4-4b6621aac05f", "type": "concept", "title": "Modeling"}, {"id": "b0863a18-3a79-49a2-8b4d-22a00ebb13ab", "type": "concept", "title": "Guided practice"}, {"id": "3d248b72-814b-4d77-872e-e8d66ec5ab2e", "type": "concept", "title": "Closure"}], "description": "Lessons translate unit goals into daily experiences with purpose, practice, and evidence."}, {"id": "b0bb4df3-f76a-401d-b0ee-607e76d1af0b", "type": "subtopic", "title": "Learning Experiences", "children": [{"id": "9df900aa-a3ef-446a-9392-e01294bfe745", "type": "concept", "title": "Inquiry"}, {"id": "86900b16-ca02-4e18-a0d8-207e0a3cbc4a", "type": "concept", "title": "Collaborative learning"}, {"id": "c78810ee-779b-4e6a-b59f-613ee1a5220d", "type": "concept", "title": "Practice and feedback"}, {"id": "ec52d67b-f3b7-4252-90cb-94558a246fa5", "type": "concept", "title": "Metacognition"}], "description": "High-quality experiences engage students in thinking, discourse, creation, and reflection."}]}, {"id": "da4abd83-6832-424b-bd11-1fa68c28dd09", "type": "topic", "title": "Differentiation, Universal Design for Learning, and Inclusive Curriculum", "description": "Plan curriculum and assessment so diverse learners can access, engage with, and demonstrate learning.", "children": [{"id": "ca9e5078-d473-42f1-aea9-6b07c83f7f1d", "type": "subtopic", "title": "Differentiation", "children": [{"id": "eb4d78b3-1dbd-4e4c-96c0-44f171597d16", "type": "concept", "title": "Readiness"}, {"id": "437bb616-c6a2-47b6-b440-e2e50d8f85a2", "type": "concept", "title": "Interest"}, {"id": "b9827001-9174-42a3-94f6-6041297ea0d3", "type": "concept", "title": "Learner profile"}, {"id": "6e9d235b-78c7-4f24-aad2-800547f80179", "type": "concept", "title": "Flexible grouping"}], "description": "Differentiation adapts content, process, product, and environment based on learner readiness, interest, and profile."}, {"id": "101c61cb-7ce5-4345-8994-efdff5f67244", "type": "subtopic", "title": "Universal Design for Learning", "children": [{"id": "55db5470-833c-46f5-aff9-98368e16048e", "type": "concept", "title": "Engagement"}, {"id": "fd8190d8-b635-4e15-a21b-03a339bceeda", "type": "concept", "title": "Representation"}, {"id": "506f2370-74a7-4f73-9218-b00e53df0265", "type": "concept", "title": "Action and expression"}, {"id": "30bf07f5-5d96-4130-b10a-4c94b93703f6", "type": "concept", "title": "Accessibility by design"}], "description": "UDL reduces barriers by planning multiple ways to engage, represent, and express learning."}, {"id": "3585c2f2-7cd8-4838-bd89-dd49a19ba859", "type": "subtopic", "title": "Inclusive Curriculum", "children": [{"id": "7f8f1e68-58df-4ac3-8d5c-a1a495aec541", "type": "concept", "title": "Culturally sustaining pedagogy"}, {"id": "2f8ff0fb-0124-4456-b145-98cd8d7313cd", "type": "concept", "title": "Multilingual learners"}, {"id": "52cfc18e-f525-4228-a8ec-fff66236ad53", "type": "concept", "title": "Disability-inclusive design"}, {"id": "09a16566-2859-4daf-91b2-1854d1ab7aa6", "type": "concept", "title": "Anti-bias materials"}], "description": "Inclusive curriculum affirms identities, builds belonging, and supports multilingual and disabled learners."}]}, {"id": "f56ff598-3aca-4a11-9b57-b650df38c24d", "type": "topic", "title": "Curriculum Mapping, Coherence, and Alignment", "description": "Map standards, objectives, instruction, assessments, materials, and progression across time.", "children": [{"id": "90e4d48e-f81c-49c7-96ef-c9465bc3a37b", "type": "subtopic", "title": "Curriculum Mapping", "children": [{"id": "e3b343a2-fc95-4910-9f6a-7abd0d8f567c", "type": "concept", "title": "Standards map"}, {"id": "7b8d3a54-26f2-4d3f-9653-6874ae135973", "type": "concept", "title": "Assessment map"}, {"id": "8d6e820c-2a73-494f-8c3f-5d96f15467d2", "type": "concept", "title": "Skill map"}, {"id": "4abaf121-757e-4130-aa38-d484332b9c07", "type": "concept", "title": "Pacing and sequence"}], "description": "Mapping makes the planned, taught, and assessed curriculum visible across units and grades."}, {"id": "9203b8a2-18b2-4118-9984-0d54c2ae0b3d", "type": "subtopic", "title": "Alignment", "children": [{"id": "e06a59cc-6ffa-4e6d-998d-9d7ddf1d612e", "type": "concept", "title": "Horizontal alignment"}, {"id": "c7c27f4f-1e24-455a-bee3-72bc4243fe6c", "type": "concept", "title": "Vertical alignment"}, {"id": "e76ab27e-41e1-4a81-be1d-d68c0a044945", "type": "concept", "title": "Cognitive demand alignment"}, {"id": "1612d230-79ef-4609-8c15-e66bc7b2343c", "type": "concept", "title": "Assessment alignment"}], "description": "Alignment checks whether goals, instruction, assessment, and materials are aiming at the same learning."}, {"id": "fac7d31b-5a5b-4c69-9f51-f494043cf486", "type": "subtopic", "title": "Curriculum Coherence", "children": [{"id": "f435cf32-c059-4d1c-8418-bf805c49f1cd", "type": "concept", "title": "Conceptual links"}, {"id": "98338bbf-211d-4eaa-8b8a-e36841f6da0f", "type": "concept", "title": "Spiraling"}, {"id": "5150cdb7-de51-40bc-99fd-953f11c463ca", "type": "concept", "title": "Interdisciplinary connections"}, {"id": "f2300899-d0d1-47c7-baa5-ce5494c7d1fb", "type": "concept", "title": "Transfer tasks"}], "description": "Coherence helps students build connected knowledge instead of fragmented topic exposure."}]}, {"id": "dc9fc3ae-fd1f-4547-a595-38796109be47", "type": "topic", "title": "Formative Assessment and Responsive Instruction", "description": "Use evidence of learning during instruction to adjust teaching, feedback, and student self-regulation.", "children": [{"id": "65b60114-ff5c-4b80-8e65-3a39fb2f2918", "type": "subtopic", "title": "Formative Assessment Purpose", "children": [{"id": "61aa0746-76a9-4385-9b49-7c5b29122f5f", "type": "concept", "title": "Learning checks"}, {"id": "d6fac1d8-4f5a-4489-bf49-8a9c7c5b93d1", "type": "concept", "title": "Exit tickets"}, {"id": "f4b2089d-a150-43d0-b3db-8571511bb217", "type": "concept", "title": "Questioning"}, {"id": "3662815e-67ba-4005-bfbe-2df053c117ff", "type": "concept", "title": "Observation"}], "description": "Formative assessment is evidence gathered to improve learning while there is still time to act."}, {"id": "bdf3866e-50bf-4a4d-9f8e-1c4f244d5061", "type": "subtopic", "title": "Responsive Teaching", "children": [{"id": "8932ea64-61e9-409b-9bda-bac21fd685d4", "type": "concept", "title": "Reteaching"}, {"id": "3ffb1e80-13a1-4080-9874-78bcc0d11ba4", "type": "concept", "title": "Enrichment"}, {"id": "4ad6205c-9737-4466-a788-2a692dd471d2", "type": "concept", "title": "Small groups"}, {"id": "9a6aa2b9-3e7f-4071-8f0f-5b9294ebb40c", "type": "concept", "title": "Misconception analysis"}], "description": "Teachers use formative evidence to adjust pacing, grouping, explanation, practice, and feedback."}, {"id": "53580c35-65a4-4dc0-b98a-f3739c1efded", "type": "subtopic", "title": "Student-Owned Assessment", "children": [{"id": "f02cd0da-f488-450b-ac02-72b1bda45b91", "type": "concept", "title": "Self-assessment"}, {"id": "2a12cb7f-8cab-4783-94e2-5833beb8c653", "type": "concept", "title": "Peer feedback"}, {"id": "c42b4cda-afbe-4f51-8c52-177a66b27ab7", "type": "concept", "title": "Goal setting"}, {"id": "49277ae3-5b81-4877-b2ec-b8e4ab4eac8c", "type": "concept", "title": "Reflection routines"}], "description": "Students learn more when assessment helps them monitor, explain, and improve their own work."}]}, {"id": "65f99de6-5517-441f-b4f7-9d921ee2b8d8", "type": "topic", "title": "Summative, Performance, and Authentic Assessment Design", "description": "Design meaningful demonstrations of learning that align to goals and transfer beyond worksheets.", "children": [{"id": "dfe09a36-3eb0-465c-b012-4c7db2c6c497", "type": "subtopic", "ti